def inspect(index: int) -> str:
            return check_fact_freshness(
                self.output,
                self.repo,
                session_id=f"concurrent-{index % 3}",
                trigger="parallel",
            )["state"]

def sharing_violation(path: Path, *args: object, **kwargs: object) -> None:
            nonlocal attempts
            if path == lock_path and attempts < 3:
                attempts += 1
                raise PermissionError(13, "fixture sharing violation", str(path), 32)
            original_unlink(path, *args, **kwargs)

def always_busy(path: Path, *args: object, **kwargs: object) -> None:
            if path == lock_path:
                raise PermissionError(13, "fixture sharing violation", str(path), 32)
            original_unlink(path, *args, **kwargs)

def test_git_tool_commands_classify_only_the_four_required_event_families(self) -> None:
        cases = {
            "git commit -m done": "commit",
            "git -C repo merge feature": "merge",
            "git.exe pull --ff-only origin main": "pull",
            "git switch topic": "branch-switch",
            "git checkout main": "branch-switch",
            "python build.py": None,
            "git status --short": None,
        }
        for command, expected in cases.items():
            with self.subTest(command=command):
                self.assertEqual(classify_git_trigger({"command": command}), expected)

def git_event(event_id: str, command: str) -> dict[str, object]:
            return ingest_event(
                "generic",
                {
                    "canonical_type": "tool.result",
                    "event_id": event_id,
                    "session_id": "e2e",
                    "turn_id": "git-events",
                    "cwd": str(self.repo),
                    "tool_name": "exec_command",
                    "tool_input": {"command": command},
                    "status": "completed",
                },
                self.registry,
            )

def _valid_template_audit_summary() -> dict[str, object]:
    summary = human_maintenance_delivery_template(
        "template", _template_review_parameters("audit", "template-audit")
    )
    statuses = {"template-review-show": "ready", "template-audit": "approved"}
    for command in summary["commands"]:
        command["literal_output"] = json.dumps({"status": statuses[command["step_id"]]})
        command["exit_status"] = 0
    summary["requirements"]["source"]["evidence"] = ["commands:template-review-show"]
    summary["requirements"]["human_review"]["evidence"] = ["commands:template-audit"]
    for field in summary["acceptance"]:
        summary["acceptance"][field] = f"verified:{field}"
    summary["rollback"]["evidence"] = ["existing-command:template rollback"]
    return summary
